    "summary": "러시아의 나트륨냉각 고속중성자로(BN-1200)가 벨로야르스크에서 2027년 건설 착수를 목표로 진행 중이다.",
    "summaryLong": "러시아가 개발 중인 나트륨냉각 고속중성자로(BN-1200)는 벨로야르스크 지역에서 2027년의 건설 착수를 목표로 하고 있다. 나트륨냉각 고속중성자로(BN-1200)는 차세대 원자로 기술로서 높은 효율성과 안전성을 갖춘 설계이다. 러시아는 핵연료 재활용과 방사성 폐기물 감량이 가능한 고속로 기술 개발을 국가 정책으로 추진하고 있다. 2027년 착공이 실현될 경우 러시아의 원자력 산업 강화와 고속로 기술의 실증화에 중요한 이정표가 될 것으로 보인다.",
