    "summaryLong": "최근 산업 분석에 따르면 소형모듈원자로는 기술적으로는 성숙도를 갖추고 있으나 경제성에서 여전히 개선이 필요한 것으로 평가되고 있다. 높은 건설비, 초기 자본 투자 부담, 대량 생산에 따른 규모의 경제 미실현 등이 주요 과제로 지적되었다. 이러한 경제성 문제는 상용화 확대와 시장 점유율 확보에 걸림돌이 될 수 있다. 업계는 대량 생산 체계 구축과 비용 최적화 방안 추진을 통해 경쟁력 제고에 주력하고 있다.",
