    "summaryLong": "인도네시아, 미국, 일본이 소형모듈원자로(SMR)의 실제 배치와 활용 방안을 논의하는 국제 컨퍼런스를 공동으로 개최했다. 이 행사는 아시아·태평양 지역의 소형모듈원자로 도입 활성화와 국제 협력 강화를 목표로 마련되었다. 세 국가의 정부 관계자, 산업계, 전문가들이 참여하여 기술 표준, 규제 체계, 사업화 전략 등을 공유했다. 이러한 국제 협력은 지역 에너지 안보와 탄소감축 목표 달성을 위한 소형모듈원자로의 역할을 강조하고 있다.",
