    "summaryLong": "금융 매체가 소형모듈원자로 산업 관련 여러 상장사들의 주식 투자 가치를 종합적으로 분석했다. 각 기업의 기술 경쟁력, 프로젝트 진척 현황, 시장 전망, 주가 흐름 등을 평가 대상으로 삼았다. 소형모듈원자로 시장의 성장성과 상용화 일정이 투자자의 포트폴리오 선택에 영향을 미치고 있다. 신흥 에너지 분야로서 소형모듈원자로 산업의 투자 기회와 위험 요소를 균형있게 제시하고 있다.",
