    "summaryLong": "에너지 기업 미국 에너지(AES)는 퍼듀대학(Purdue University)에서 개최된 핵 정상회담에서 소형모듈원자로(SMR) 관련 기술 또는 사업 추진 현황을 발표했다. 퍼듀대학(Purdue University) 핵 정상회담은 원자력 에너지의 미래와 산업 발전 방향을 논의하는 주요 행사로, 미국 에너지(AES)의 발표는 업계의 관심을 모았다. 이를 통해 미국 에너지(AES)는 소형모듈원자로(SMR) 분야에서의 기술 역량과 사업 전략을 대외적으로 알릴 수 있었다. 이는 소형모듈원자로(SMR) 산업의 발전과 관련 투자 확대를 촉진하는 데 긍정적인 영향을 미칠 것으로 예상된다.",
